contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint putLock, uint putVal, uint collectAmt) public payable {
        require(address(this).balance >= putVal);

        // Ensure LogFile and MinSum can be set before initialization by calling SetMinSum and SetLogFile
        // These calls may revert if already initialized in some other scenario, but per problem statement
        // c is freshly deployed so it's allowed. We avoid assuming specific addresses for Log; pass zero.
        // Observe: these calls change c's state and must be top-level statements.
        c.SetMinSum(0);
        c.SetLogFile(address(0));

        // Put some funds into the contract for this test account (msg.sender for c will be this contract)
        // Call Put with ether amount putVal and lock putLock
        c.Put{value: putVal}(putLock);

        // Read balances before Collect attempt
        uint beforeHolderBal = c.Acc(address(this)).balance;
        uint beforeContractBal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after Collect attempt
        uint afterHolderBal = c.Acc(address(this)).balance;
        uint afterContractBal = address(c).balance;

        // General invariant: Collect cannot increase the holder's recorded balance or the contract's balance.
        // I.e., after the call (whether it reverted or not), both balances are <= before values.
        assert(afterHolderBal <= beforeHolderBal && afterContractBal <= beforeContractBal);
    }

    // allow this contract to receive Ether so it can call c functions with value
    receive() external payable {}
}

