        midHolderBal = c.Acc(address(this)).balance;
        midContractBal = address(c).balance;

        // attempt Collect and catch revert
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterHolderBal = c.Acc(address(this)).balance;
