contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) ensure MinSum is 0 and Initialized is true so Collect's MinSum check won't block
    // 2) deposit some Ether via Put so there is a balance to collect
    // 3) try Collect and observe whether it reverted; if it did not revert then require that
    //    the recorded balance and contract balance decreased by exactly the amount collected.
    function run(uint lockTimePut, uint deposit, uint collectAmount) public payable {
        // need Ether to deposit
        require(address(this).balance >= deposit);
        // ensure MinSum is zero so MinSum check in Collect does not prevent collection
        // SetMinSum and SetLogFile can revert if contract already initialized; since c is fresh it's safe
        c.SetMinSum(0);
        // Set a trivial log (address 0) — LogFile is an address typed to Log; using address(0) is allowed
        c.SetLogFile(address(0));
        c.Initialized();

        // read-before values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // deposit deposit wei using Put
        c.Put{value: deposit}(lockTimePut);

        // read values after deposit and before collect attempt
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // mid balances should have increased by deposit (observable requirement to make collect meaningful)
        // We require this to avoid trivial counterexamples where deposit didn't increase (should hold given Put semantics)
        require(midBal >= beforeBal);
        require(midContractBal >= beforeContractBal);

        bool reverted;
        // attempt Collect; it may revert due to unlockTime or insufficient balance; catch that
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect did not revert then the recorded balance and the contract Ether balance must have decreased by exactly collectAmount.
        // We assert that either it reverted OR both balances decreased by collectAmount.
        assert(reverted || (midBal >= collectAmount && midContractBal >= collectAmount && afterBal + collectAmount == midBal && afterContractBal + collectAmount == midContractBal));
    }

    // receive to accept refunds/transfers if needed during Collect
    receive() external payable {}
}

