contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call with an amount to send and a lock time. We require this contract has enough balance.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read balance before
        (uint beforeUnlock, uint beforeBal) = _getAcc();
        uint beforeContractBal = address(c).balance;

        // Perform Put with the given amount
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = _getAcc();
        uint afterContractBal = address(c).balance;

        // If the call reverted then nothing is guaranteed about state changes here.
        // Otherwise, balance observed in Acc must have increased by exactly amount
        // (or remained same if addition would have overflowed — but Solidity 0.8 reverts on overflow, so revert covers that case).
        // Also, contract balance must have increased by at least amount.
        assert( reverted || ( afterBal == beforeBal + amount && afterContractBal >= beforeContractBal + amount ) );
    }

    // helper to call the public getter Acc(address) which returns Holder struct fields
    function _getAcc() internal view returns (uint unlockTime, uint balance) {
        // The compiler auto-generated getter for Acc returns (uint,uint)
        (unlockTime, balance) = c.Acc(address(this));
    }

    // receive to accept refunds if any
    receive() external payable {}
}

