        require(address(this).balance >= depositAmount);

        // Make an initial Put to ensure Acc[this] has funds and an unlockTime in the past/future depending on lockTime
        bool putReverted;
        try c.Put{value: depositAmount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read observed before-values from the public surface
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
