contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: deposit to Put, lockTime for Put, amount to try to Collect
    function run(uint depositAmount, uint lockTime, uint collectAmount) public payable {
        // ensure this test contract can fund the Put call
        require(address(this).balance >= depositAmount);

        // perform a Put to set up Acc for this caller
        bool putReverted;
        try c.Put{value: depositAmount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read public observable before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint minSum = c.MinSum();

        // attempt Collect and capture whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // If Collect succeeded, then the contract's own checks required: beforeBal >= minSum, beforeBal >= collectAmount, and block.timestamp > beforeUnlock.
        // We cannot read block.timestamp of c, but beforeUnlock is public and the condition block.timestamp > beforeUnlock is required by Collect for success.
        // The asserted implication: if Collect did not revert, then both numeric comparisons held and beforeUnlock < block.timestamp (we approximate by requiring beforeUnlock < block.timestamp of this tx via a conservative check using now-like semantics: block.timestamp >= beforeUnlock+1 implies block.timestamp > beforeUnlock).
        // Since we cannot read c's block.timestamp separately, use the fact that this call's block.timestamp is the same for all calls in this transaction. We assert using a relation with beforeUnlock and require that beforeUnlock < block.timestamp (i.e., beforeUnlock + 1 <= block.timestamp).

        // make the single final general assertion
        assert( collectReverted || (beforeBal >= minSum && beforeBal >= collectAmount && beforeUnlock < block.timestamp) );
    }

    // receive to accept ETH transfers from C if Collect sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will drive Put to fund this contract's holder entry, then attempt Collect.
    // Inputs:
    //  putAmount - amount of wei to send in Put
    //  lockTime - lock extension passed to Put
    //  collectAmount - amount requested in Collect
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for Put");

        // Ensure MinSum is zero so Collect's MinSum check won't block if intended.
        // Use SetMinSum before Initialized (allowed) to set MinSum = 0.
        c.SetMinSum(0);

        // Call Put with value putAmount to increase this contract's recorded balance in c.
        c.Put{value: putAmount}(lockTime);

        // Read recorded balance before Collect
        (uint beforeBalance, ) = _getAccForThis();

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded balance after Collect
        (uint afterBalance, ) = _getAccForThis();

        // Rule: If Collect succeeded then collectAmount cannot exceed beforeBalance,
        // and afterBalance == beforeBalance - collectAmount.
        // If Collect reverted then afterBalance == beforeBalance (no change).
        assert( (!reverted && collectAmount <= beforeBalance && afterBalance == beforeBalance - collectAmount)
                || (reverted && afterBalance == beforeBalance) );
    }

    // helper to call public Acc getter: Acc(address) returns (uint unlockTime, uint balance)
    function _getAccForThis() internal returns (uint,uint) {
        // The auto-generated getter for mapping (address => Holder) public Acc returns (uint,uint)
        return c.Acc(address(this));
    }

    receive() external payable {}
}

