contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs:
    // putAmount: wei to send in Put
    // lockTime: parameter to Put
    // collectAmount: parameter to Collect
    function run(uint putAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance for Put");

        // Make MinSum zero so it won't block Collect unexpectedly
        c.SetMinSum(0);

        // Fund this test contract's holder entry in c
        c.Put{value: putAmount}(lockTime);

        // Record holder balance and contract balance before Collect
        (, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value:0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record holder balance and contract balance after Collect
        (, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then: afterBal == beforeBal - withdrawnAmount, and contract balance decreased by at least withdrawnAmount.
        // We can't directly observe the ETH transferred to msg.sender inside c except via contract balance change and Acc change.
        // withdrawnAmount is the decrease in the recorded balance when Collect succeeded.
        uint withdrawnAmount = 0;
        if (beforeBal >= afterBal) {
            withdrawnAmount = beforeBal - afterBal;
        }

        assert(
            (reverted && afterBal == beforeBal)
            ||
            (!reverted && afterBal + withdrawnAmount == beforeBal && beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal >= withdrawnAmount)
        );
    }

    receive() external payable {}
}
